SELECT sku, product_name, pack_size, flow_type, selling_price_inr, cost_price_inr, units_per_case
FROM store.products
ORDER BY sku;

SELECT sku, name, pack, flow, price_inr, cost_inr, case_units, dc_slot
FROM store.products
ORDER BY sku;

SELECT (SELECT min(date) FROM store.daily_sales) AS min_date,
       (SELECT max(date) FROM store.daily_sales) AS max_date,
       (SELECT count(*) FROM store.daily_sales WHERE sku = 'ATTA-WW-5KG' AND date >= '2026-06-29') AS rows_jun29_30;
